import SwiftUI
import Firebase

struct NewsFeedView: View {
  @State private var newsItems: [NewsItem] = []
  @State private var userLocation: String?
  @State private var userAge: Int?

  private func fetchNewsItems() {
    // Get the user's location and age
    guard let userLocation = userLocation, let userAge = userAge else { return }

    // Create a dictionary of news items
    let newsItems: [NewsItem] = [
      NewsItem(title: "Local Tax Reform Proposal Sparks Debate", content: "A proposed tax reform bill has sparked widespread debate in the community."),
      NewsItem(title: "Experts Say Tax Reform Could Impact Economy", content: "Economic experts have weighed in on the proposed tax reform, offering various perspectives."),
      NewsItem(title: "Young Adults Concerned About Affordability", content: "Young adults are voicing concerns about the affordability of the proposed tax reform."),
      NewsItem(title: "Local Business Owners Weigh In", content: "Local business owners have expressed their concerns about the potential impact of the tax reform."),
      NewsItem(title: "Community Leaders Call for Compromise", content: "Community leaders have called for compromise on the proposed tax reform.")
    ]

    // Filter the news items based on the user's demographics
    self.newsItems = newsItems.filter { item in
      // Include items that are relevant to the user's location
      item.location.contains(userLocation)

      // Include items that are relevant to the user's age
      item.ageGroup.contains(userAge)
    }
  }

  var body: some View {
    VStack {
      List(newsItems) { item in
        NewsItemCell(item: item)
      }
    }
    .onAppear {
      fetchNewsItems()
    }
  }
}

